/// Private module environment owner; the facade creates one per Worker.
#[derive(Debug)]
#[napi]
pub struct NativeEnvironment {
    state: Arc<Environment>,
}

#[napi]
impl NativeEnvironment {
    /// Registers native-only environment cleanup.
    #[napi(constructor)]
    pub fn new(env: Env) -> Result<Self> {
        let state = Arc::new(Environment::default());
        env.add_env_cleanup_hook(Arc::clone(&state), |state| state.close())?;
        Ok(Self { state })
    }
    /// Constructs a reusable client without caching this Env.
    #[napi]
    pub fn client(
        &self,
        env: Env,
        mut options: ClientOptions,
        profile: Option<&NativeProfile>,
    ) -> Result<NativeClient> {
        let profile = match (options.profile.take(), profile) {
            (Some(identifier), None) => ProfileState::catalog(&identifier, None)?,
            (None, Some(profile)) => Arc::clone(&profile.state),
            _ => {
                return Err(failure(
                    "InvalidProfile",
                    "choose an exact identifier or a Profile",
                ));
            }
        };
        let copy_roots = |roots: Option<Vec<Buffer>>| {
            let roots = roots.unwrap_or_default();
            if roots.len() > 16 {
                return Err(failure("InputLimit", "too many additional trust roots"));
            }
            roots
                .into_iter()
                .map(|root| copy_buffer(&env, root, 1024 * 1024))
                .collect::<Result<Vec<_>>>()
        };
        let roots = copy_roots(options.additional_roots.take())?;
        let proxy_roots = copy_roots(options.additional_proxy_roots.take())?;
        ClientState::build(options, profile, roots, proxy_roots, &self.state)
            .map(|state| NativeClient { state })
    }

    /// Registers an independent client with explicitly selected native state.
    #[napi]
    pub fn fork(
        &self,
        source: &NativeClient,
        sharing: SessionSharingOptions,
    ) -> Result<NativeClient> {
        let sharing = phantom::SessionSharing::none()
            .cookies(sharing.cookies.unwrap_or(false))
            .dns(sharing.dns.unwrap_or(false))
            .client_hints(sharing.client_hints.unwrap_or(false))
            .discovery(sharing.discovery.unwrap_or(false))
            .tickets(sharing.tickets.unwrap_or(false));
        source
            .state
            .fork(sharing, &self.state)
            .map(|state| NativeClient { state })
    }
}

/// Immutable settings owned by Rust, without references to JavaScript inputs.
#[derive(Debug)]
#[napi]
pub struct NativeProfile {
    state: Arc<ProfileState>,
}

#[napi]
impl NativeProfile {
    /// Returns the exact catalog identity, or null for every imported profile.
    #[napi(getter)]
    #[must_use]
    pub fn catalog_id(&self) -> Option<String> {
        self.state.catalog_id()
    }

    /// Lists supported explicit contexts without substituting another template.
    #[napi(getter)]
    #[must_use]
    pub fn contexts(&self) -> Vec<String> {
        self.state.contexts()
    }

    /// Exports the core's editable JSON document into a fresh owned Buffer.
    #[napi]
    pub fn export_json(&self) -> Result<Buffer> {
        self.state.export().map(Buffer::from)
    }
}

/// Selects an exact catalog profile and optionally attaches its named template.
#[napi]
pub fn profile_catalog(identifier: String, context: Option<String>) -> Result<NativeProfile> {
    ProfileState::catalog(&identifier, context.as_deref()).map(|state| NativeProfile { state })
}

/// Copies bounded ordinary bytes on this Env before strict native JSON import.
#[napi]
pub fn profile_import_json(env: Env, input: Buffer) -> Result<NativeProfile> {
    let input = copy_buffer(&env, input, MAXIMUM_PROFILE_BYTES)?;
    ProfileState::import(&input).map(|state| NativeProfile { state })
}

/// Native shared allowance for origin HTTP attempts.
#[derive(Debug)]
#[napi]
pub struct NativeAttemptBudget {
    budget: phantom::HttpAttemptBudget,
}

#[napi]
impl NativeAttemptBudget {
    /// Creates one counter shared by every request receiving this object.
    #[napi(constructor)]
    pub fn new(maximum: BigInt) -> Result<Self> {
        let maximum = match (maximum.sign_bit, maximum.words.as_slice()) {
            (false, [value]) => usize::try_from(*value).ok(),
            _ => None,
        }
        .ok_or_else(|| failure("InvalidArgument", "maximum must fit usize"))?;
        Ok(Self {
            budget: phantom::HttpAttemptBudget::new(maximum),
        })
    }
    /// Returns a snapshot, not a reservation.
    #[napi(getter)]
    #[must_use]
    pub fn remaining(&self) -> Either<f64, BigInt> {
        let remaining = self.budget.remaining() as u64;
        if remaining < (1_u64 << 53) {
            Either::A(remaining as f64)
        } else {
            Either::B(BigInt {
                sign_bit: false,
                words: vec![remaining],
            })
        }
    }
    /// Charges an external attempt; Phantom requests already charge themselves.
    #[napi]
    pub fn try_admit(&self) -> Result<()> {
        self.budget.try_admit().map_err(|_| {
            failure(
                "AttemptBudgetExhausted",
                "shared HTTP attempt budget exhausted",
            )
        })
    }
}

/// One request's native cancellation and body owner.
#[derive(Debug)]
#[napi]
pub struct NativeCancellation {
    exchange: Arc<Exchange>,
}

#[napi]
impl NativeCancellation {
    /// Creates a handle usable by one request.
    #[napi(constructor)]
    #[must_use]
    pub fn new() -> Self {
        Self {
            exchange: Exchange::new(),
        }
    }
    /// Cancels setup, upload or response reading and drops any idle body.
    #[napi]
    pub fn cancel(&self) {
        self.exchange.cancel();
    }
}

impl Default for NativeCancellation {
    fn default() -> Self {
        Self::new()
    }
}

/// Reusable native client.
#[derive(Debug)]
#[napi]
pub struct NativeClient {
    state: Arc<ClientState>,
}

#[napi]
impl NativeClient {
    /// Closes idle origin and proxy connections without closing this client.
    #[napi]
    pub fn close_idle_connections(&self, env: Env) -> Result<AsyncBlock<()>> {
        self.state.check_open()?;
        let owner = Arc::clone(&self.state);
        AsyncBlockBuilder::new(async move {
            owner.core.close_idle_connections().await;
            Ok(())
        })
        .build(&env)
    }
    /// Retires connections while retaining compatible session state.
    #[napi]
    pub fn refresh_connections(&self, env: Env) -> Result<AsyncBlock<()>> {
        self.state.check_open()?;
        let owner = Arc::clone(&self.state);
        AsyncBlockBuilder::new(async move {
            owner.core.refresh_connections().await;
            Ok(())
        })
        .build(&env)
    }
    /// Clears the native DNS cache.
    #[napi]
    pub fn clear_dns_cache(&self) -> Result<()> {
        self.state.check_open()?;
        self.state.core.clear_dns_cache();
        Ok(())
    }
    /// Clears advertised alternatives and their racing history.
    #[napi]
    pub fn clear_alt_svc(&self) -> Result<()> {
        self.state.check_open()?;
        self.state.core.clear_alt_svc();
        Ok(())
    }
    /// Clears racing history while retaining advertised alternatives.
    #[napi]
    pub fn clear_alt_svc_racing_history(&self) -> Result<()> {
        self.state.check_open()?;
        self.state.core.clear_alt_svc_racing_history();
        Ok(())
    }
    /// Clears learned client hints.
    #[napi]
    pub fn clear_client_hints(&self) -> Result<()> {
        self.state.check_open()?;
        self.state.core.clear_client_hints();
        Ok(())
    }
    /// Clears retained TLS tickets and returns the removed count.
    #[napi]
    pub fn clear_session_tickets(&self) -> Result<u32> {
        self.state.check_open()?;
        let count = self
            .state
            .core
            .clear_session_tickets()
            .map_err(|_| failure("SessionTickets", "session tickets could not be cleared"))?;
        u32::try_from(count)
            .map_err(|_| failure("Capacity", "ticket count exceeds the supported range"))
    }
    /// Clears this client's native cookie jar.
    #[napi]
    pub fn clear_cookies(&self) -> Result<()> {
        self.state.check_open()?;
        self.state
            .core
            .cookie_jar()
            .ok_or_else(|| failure("CookiesDisabled", "cookie handling is disabled"))?
            .clear();
        Ok(())
    }
    /// Copies JS-owned input before scheduling a native-owned request future.
    #[napi]
    pub fn request(
        &self,
        env: Env,
        mut options: RequestOptions,
        cancellation: &NativeCancellation,
        budget: Option<&NativeAttemptBudget>,
    ) -> Result<AsyncBlock<NativeResponse>> {
        let started = Instant::now();
        let fields = options.headers.take().unwrap_or_default();
        if fields.len() > 256 {
            return Err(failure("InputLimit", "too many request headers"));
        }
        let mut remaining = MAXIMUM_HEADER_BYTES;
        let mut headers = Vec::with_capacity(fields.len());
        for field in fields {
            remaining = remaining
                .checked_sub(field.name.len())
                .ok_or_else(|| failure("InputLimit", "request headers exceed the binding limit"))?;
            let value = copy_buffer(&env, field.value, remaining)?;
            remaining -= value.len();
            let header = phantom::RequestHeader::new(field.name, value);
            headers.push(if field.sensitive.unwrap_or(false) {
                header.sensitive()
            } else {
                header
            });
        }
        let body = options
            .body
            .take()
            .map(|body| copy_buffer(&env, body, MAXIMUM_INPUT_BYTES))
            .transpose()?;
        let prepared = Prepared::new(
            &self.state,
            options,
            headers,
            body,
            started,
            Arc::clone(&cancellation.exchange),
            budget.map(|budget| budget.budget.clone()),
        )?;
        let owner = Arc::clone(&self.state);
        AsyncBlockBuilder::new(async move {
            let (head, exchange) = prepared.send().await?;
            Ok(NativeResponse {
                status: head.status,
                headers: head.headers,
                protocol: head.protocol,
                url: head.url,
                redirects: head.redirects,
                connection_retries: head.connection_retries,
                decoded_content_codings: head.decoded_content_codings,
                redirect_history: head.redirect_history,
                exchange,
                owner,
            })
        })
        .build(&env)
    }
    /// Cancels this client's owned work, then waits for public shutdown.
    #[napi]
    pub fn close(&self, env: Env, timeout_ms: u32) -> Result<AsyncBlock<()>> {
        self.state.close();
        let shutdown = self.state.shutdown()?;
        let client = self.state.core.clone();
        AsyncBlockBuilder::new(async move {
            let _shutdown = shutdown;
            tokio::time::timeout(
                Duration::from_millis(u64::from(timeout_ms)),
                client.shutdown(),
            )
            .await
            .map_err(|_| failure("Timeout", "client shutdown deadline expired"))
        })
        .build(&env)
    }
    /// Adds a cookie through the native jar without exposing error inputs.
    #[napi]
    pub fn set_cookie(&self, url: String, cookie: String) -> Result<()> {
        self.state
            .core
            .cookie_jar()
            .ok_or_else(|| failure("CookiesDisabled", "cookie handling is disabled"))?
            .set_cookie(&url, &cookie)
            .map_err(|_| failure("InvalidCookie", "cookie could not be stored"))
    }
    /// Returns the jar's request value for this URL.
    #[napi]
    pub fn cookie_value(&self, url: String) -> Result<Option<String>> {
        self.state
            .core
            .cookie_jar()
            .ok_or_else(|| failure("CookiesDisabled", "cookie handling is disabled"))?
            .request_value(&url)
            .map_err(|_| failure("InvalidCookie", "cookie URL is invalid"))
    }
}

/// Response head and one pull-driven native body.
#[napi]
pub struct NativeResponse {
    status: u32,
    headers: Vec<(String, Vec<u8>)>,
    protocol: String,
    url: String,
    redirects: u32,
    connection_retries: u32,
    decoded_content_codings: Vec<String>,
    redirect_history: Option<RedirectHistoryInfo>,
    exchange: Arc<Exchange>,
    owner: Arc<ClientState>,
}

impl fmt::Debug for NativeResponse {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("NativeResponse")
            .field("status", &self.status)
            .finish_non_exhaustive()
    }
}

#[napi]
impl NativeResponse {
    /// Actual protocol that produced this response.
    #[napi(getter)]
    #[must_use]
    pub fn protocol(&self) -> String {
        self.protocol.clone()
    }
    /// Final URL after following redirects.
    #[napi(getter)]
    #[must_use]
    pub fn url(&self) -> String {
        self.url.clone()
    }
    /// Number of redirects followed for this logical request.
    #[napi(getter)]
    #[must_use]
    pub fn redirects(&self) -> u32 {
        self.redirects
    }
    /// Connection-setup retries, excluding other replay classes.
    #[napi(getter)]
    #[must_use]
    pub fn connection_retries(&self) -> u32 {
        self.connection_retries
    }
    /// Selected coding chain in Content-Encoding order, not completion status.
    #[napi(getter)]
    #[must_use]
    pub fn decoded_content_codings(&self) -> Vec<String> {
        self.decoded_content_codings.clone()
    }
    /// First retained redirects, or no history when not requested.
    #[napi(getter)]
    #[must_use]
    pub fn redirect_history(&self) -> Option<RedirectHistoryInfo> {
        self.redirect_history.clone()
    }
    /// HTTP status received from the peer.
    #[napi(getter)]
    #[must_use]
    pub fn status(&self) -> u32 {
        self.status
    }
    /// Response fields retaining duplicate positions and byte values.
    #[napi(getter)]
    #[must_use]
    pub fn headers(&self) -> Vec<WireHeader> {
        self.headers
            .iter()
            .map(|(name, value)| WireHeader {
                name: name.clone(),
                value: value.clone().into(),
                sensitive: None,
            })
            .collect()
    }
    /// Reads at most the requested bytes without polling ahead.
    #[napi]
    pub fn read(&self, env: Env, maximum_bytes: u32) -> Result<AsyncBlock<Option<Buffer>>> {
        let exchange = Arc::clone(&self.exchange);
        let owner = Arc::clone(&self.owner);
        AsyncBlockBuilder::new(async move {
            let _owner = owner;
            exchange
                .read(maximum_bytes)
                .await
                .map(|bytes| bytes.map(Buffer::from))
        })
        .build(&env)
    }
    /// Collects the remaining body under one exclusive reader and byte limit.
    #[napi]
    pub fn collect(&self, env: Env, maximum_bytes: u32) -> Result<AsyncBlock<Buffer>> {
        let exchange = Arc::clone(&self.exchange);
        let owner = Arc::clone(&self.owner);
        AsyncBlockBuilder::new(async move {
            let _owner = owner;
            exchange.collect(maximum_bytes).await.map(Buffer::from)
        })
        .build(&env)
    }
    /// Cancels and releases an unfinished body.
    #[napi]
    pub fn close(&self) {
        self.exchange.cancel();
    }
}

impl Drop for NativeResponse {
    fn drop(&mut self) {
        self.exchange.cancel();
    }
}

/// Lists exact compiled identifiers without maintaining a second registry.
#[napi]
#[must_use]
pub fn profile_ids() -> Vec<String> {
    phantom_profile::catalog::profiles()
        .iter()
        .map(|profile| profile.id().as_str().to_owned())
        .collect()
}
